def fusionar(intervalos):
       if not intervalos:
           return []

       # Sort by start time
       intervalos_ordenados = sorted(intervalos, key=lambda x: x[0])

       fusionados = [intervalos_ordenados[0]]

       for inicio, fin in intervalos_ordenados[1:]:
           ultimo_inicio, ultimo_fin = fusionados[-1]

           if inicio <= ultimo_fin:
               # Se tocan o se solapan, se fusionan
               # Actualizamos el fin del último intervalo si es necesario
               fusionados[-1] = (ultimo_inicio, max(ultimo_fin, fin))
           else:
               # No hay solapamiento, agregamos el nuevo intervalo
               fusionados.append((inicio, fin))

       return fusionados

