def balanceado(text):
    stack = []
    opening = {'(', '[', '{'}
    matching = {')': '(', ']': '[', '}': '{'}

    for char in text:
        if char in opening:
            stack.append(char)
        elif char in matching:
            if not stack or stack[-1] != matching[char]:
                return False
            stack.pop()
    return len(stack) == 0

