def contar_islas(grid):
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                stack = [(i, j)]
                grid[i][j] = 0  # marcar como visitado
                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1:
                            grid[nx][ny] = 0
                            stack.append((nx, ny))
                count += 1
    return count

def validar_password(p):
        # Check length
        if len(p) < 8:
            return False
        # Check uppercase
        if not any(c.isupper() for c in p):
            return False
        # Check lowercase
        if not any(c.islower() for c in p):
            return False
        # Check digit
        if not any(c.isdigit() for c in p):
            return False
        # Check non-alphanumeric
        if not any(not c.isalnum() for c in p):
            return False
        return True

